        'maxWaitMs: ${maxWait.inMilliseconds}\n'
        'maxWaitForLastEntryMs: ${maxWaitForLastEntry.inMilliseconds}\n'
        'keyBackoffMs: ${keyBackoff.inMilliseconds}\n';
  }
}

