  TextDeltaEvent(:final delta) => 'delta:$delta',
  DoneEvent(:final message) => 'done:${message.model}',
  ErrorEvent(:final reason, :final error) =>
    'error(${reason.name}):${error.model}:${error.errorMessage}',
  _ => event.runtimeType.toString(),
};

