      providerTimeoutsOverride = parseProviderTimeouts(
        doc is YamlMap ? doc['providerTimeouts'] : null,
      );
    case Err():
      // The write just succeeded; a read race keeps the current live
      // override — the next write re-syncs.
      break;
  }
}

