921:  /// Every key of [entry] is benched right now: wait for the earliest to
922:  /// free up, or fail over when the retries are spent / the wait exceeds
923:  /// the cap. Returns false when the run ends (exhausted or aborted).
924:  Future<bool> _onNoCredential(
925:    AssistantMessageEventStream out,
926:    _DriveState state,
927:    ChainEntry entry,
928:    CancelToken? cancelToken,
929:  ) async {
930:    if (state.attemptsOnEntry >= policy.retriesPerEntry) {
931:      return _failOver(out, state);
932:    }
